import fs from 'fs';
import path from 'path';

// Valid 1-second silent MP3 (44.1kHz, 128kbps, CBR)
// Source: Generated via FFmpeg and converted to Base64
const validMp3Base64 = ""

const buffer = Buffer.from(validMp3Base64, 'base64');
const files = ['lesson-1.mp3', 'lesson-2.mp3'];

files.forEach(fileName => {
    const targetPath = path.join(process.cwd(), 'public/audio', fileName);
    try {
        fs.writeFileSync(targetPath, buffer);
        console.log(`Successfully created valid MP3 at ${targetPath} (Size: ${buffer.length} bytes)`);
    } catch (err) {
        console.error(`Failed to write ${fileName}:`, err);
    }
});
